//go:build e2e

// Package e2e drives the full docker-compose stack through real HTTP, direct
// Postgres reads, and direct Kafka consumption — SPEC.md §10.3's TST-E2E-1..4 and
// TST-E2E-6, plus Milestone 6's deposits, withdrawals, wallet lifecycle,
// reconciliation and rebuild-during-lag scenarios.
// Run via `make test-e2e` after `make up`; never invoked by `make test` or CI
// (no compose orchestration there). Requires keys/private.pem to already
// exist (generated by scripts/generate-jwt.sh or any prior `make up`).
package e2e

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/golang-jwt/jwt/v5"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/twmb/franz-go/pkg/kgo"
)

const (
	walletBaseURL = "http://localhost:8080"
	ledgerBaseURL = "http://localhost:8081"
	postgresDSN   = "postgres://ledger_app:ledger_app@localhost:5432/ledger?sslmode=disable"
	// ownerDSN is the database owner. ledger_app (postgresDSN) cannot write projection_db or
	// read wallet_db, and two M6 tests must: corrupting a projection on purpose (TST-E2E-6) and
	// reading the wallet audit log.
	ownerDSN    = "postgres://ledger:ledger@localhost:5432/ledger?sslmode=disable"
	kafkaBroker = "localhost:9092"
	ledgerTopic = "ledger.posted.v1"
	// systemAccountID mirrors ADR-0008's default SYSTEM_ACCOUNT_ID.
	systemAccountID = "00000000-0000-0000-0000-000000000001"
)

// signJWT mirrors scripts/generate-jwt.sh's claims shape (sub, role, iat,
// exp) and signing key (keys/private.pem, RS256) exactly, so tokens minted
// here are interchangeable with ones the shell script would produce.
func signJWT(t *testing.T, userID uuid.UUID, role string) string {
	t.Helper()

	keyPath := os.Getenv("E2E_PRIVATE_KEY_PATH")
	if keyPath == "" {
		keyPath = "../../keys/private.pem"
	}
	pemBytes, err := os.ReadFile(keyPath)
	if err != nil {
		t.Fatalf("read private key at %s (run scripts/generate-jwt.sh once, or `make up`, to generate it): %v", keyPath, err)
	}
	key, err := jwt.ParseRSAPrivateKeyFromPEM(pemBytes)
	if err != nil {
		t.Fatalf("parse RSA private key: %v", err)
	}

	now := time.Now()
	claims := jwt.MapClaims{
		"sub":  userID.String(),
		"role": role,
		"iat":  now.Unix(),
		"exp":  now.Add(24 * time.Hour).Unix(),
	}
	token := jwt.NewWithClaims(jwt.SigningMethodRS256, claims)
	signed, err := token.SignedString(key)
	if err != nil {
		t.Fatalf("sign JWT: %v", err)
	}
	return signed
}

func doRequest(t *testing.T, method, url, bearerToken, body string) *http.Response {
	t.Helper()
	req, err := http.NewRequest(method, url, strings.NewReader(body))
	if err != nil {
		t.Fatalf("build request: %v", err)
	}
	req.Header.Set("Content-Type", "application/json")
	if bearerToken != "" {
		req.Header.Set("Authorization", "Bearer "+bearerToken)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("%s %s: %v", method, url, err)
	}
	return resp
}

func readBody(t *testing.T, resp *http.Response) string {
	t.Helper()
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("read response body: %v", err)
	}
	return string(b)
}

// newWallet creates a wallet for ownerID and returns its ID. Each E2E test
// uses a fresh random ownerID per run so reruns against a warm stack never
// collide with a previous run's wallets.
func newWallet(t *testing.T, token string, ownerID uuid.UUID) uuid.UUID {
	t.Helper()
	body := fmt.Sprintf(`{"ownerId":"%s","currency":"BRL"}`, ownerID)
	resp := doRequest(t, http.MethodPost, walletBaseURL+"/wallets", token, body)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusCreated {
		t.Fatalf("POST /wallets = %d, want 201; body: %s", resp.StatusCode, readBody(t, resp))
	}
	var created struct {
		WalletID string `json:"walletId"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&created); err != nil {
		t.Fatalf("decode wallet creation response: %v", err)
	}
	return uuid.MustParse(created.WalletID)
}

// seedDeposit funds destinationWallet through the public API: an admin POST /deposits (FR-6).
// Every test that funds a wallet therefore also exercises Task 03's endpoint.
func seedDeposit(t *testing.T, destinationWallet uuid.UUID, amount string) {
	t.Helper()
	_, admin := newAdmin(t)
	resp, body := postDeposit(t, admin, uuid.New().String(), destinationWallet, amount)
	if resp.StatusCode != http.StatusCreated {
		t.Fatalf("seed deposit POST /deposits = %d, want 201; body: %s", resp.StatusCode, body)
	}
}

// newAdmin mints an admin token for a fresh admin user id.
func newAdmin(t *testing.T) (uuid.UUID, string) {
	t.Helper()
	id := uuid.New()
	return id, signJWT(t, id, "admin")
}

// postWithKey issues a JSON POST with an optional Idempotency-Key and returns the response plus
// its already-read body (resp.Body is consumed).
func postWithKey(t *testing.T, url, token, idempotencyKey, body string) (*http.Response, string) {
	t.Helper()
	req, err := http.NewRequest(http.MethodPost, url, strings.NewReader(body))
	if err != nil {
		t.Fatalf("build request: %v", err)
	}
	req.Header.Set("Content-Type", "application/json")
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	if idempotencyKey != "" {
		req.Header.Set("Idempotency-Key", idempotencyKey)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("POST %s: %v", url, err)
	}
	defer resp.Body.Close()
	return resp, readBody(t, resp)
}

// postDeposit issues POST /deposits (admin only, FR-6).
func postDeposit(t *testing.T, token, idempotencyKey string, destination uuid.UUID, amount string) (*http.Response, string) {
	t.Helper()
	return postWithKey(t, walletBaseURL+"/deposits", token, idempotencyKey,
		fmt.Sprintf(`{"destinationWalletId":"%s","amount":"%s"}`, destination, amount))
}

// postWithdrawal issues POST /withdrawals (admin only, FR-7).
func postWithdrawal(t *testing.T, token, idempotencyKey string, source uuid.UUID, amount string) (*http.Response, string) {
	t.Helper()
	return postWithKey(t, walletBaseURL+"/withdrawals", token, idempotencyKey,
		fmt.Sprintf(`{"sourceWalletId":"%s","amount":"%s"}`, source, amount))
}

// walletAction issues POST /wallets/{id}/{freeze|unfreeze|close} with the owner's token.
func walletAction(t *testing.T, token string, walletID uuid.UUID, action string) (*http.Response, string) {
	t.Helper()
	return postWithKey(t, fmt.Sprintf("%s/wallets/%s/%s", walletBaseURL, walletID, action), token, "", "")
}

// rebuildProjection hits the Wallet Service's admin rebuild (Task 05) -- the path an operator
// uses -- not the Projection Service's internal one.
func rebuildProjection(t *testing.T, token string, walletID uuid.UUID) (*http.Response, string) {
	t.Helper()
	return postWithKey(t, fmt.Sprintf("%s/admin/projections/%s/rebuild", walletBaseURL, walletID), token, "", "")
}

// corruptProjection overwrites a wallet's projected balance directly, as the database owner.
func corruptProjection(t *testing.T, walletID uuid.UUID, balance string) {
	t.Helper()
	ownerExec(t, `UPDATE projection_db.wallet_balances SET balance = $2::numeric WHERE wallet_id = $1`, walletID, balance)
}

func ownerExec(t *testing.T, sql string, args ...any) {
	t.Helper()
	conn, err := pgx.Connect(context.Background(), ownerDSN)
	if err != nil {
		t.Fatalf("connect as owner: %v", err)
	}
	defer conn.Close(context.Background())
	tag, err := conn.Exec(context.Background(), sql, args...)
	if err != nil {
		t.Fatalf("owner exec: %v", err)
	}
	if tag.RowsAffected() == 0 {
		t.Fatalf("owner exec affected no rows: %s", sql)
	}
}

// reconciliationReport is Task 06's report contract (handler/reconciliation.go).
type reconciliationReport struct {
	Clean     bool `json:"clean"`
	Invariant struct {
		Clean        bool `json:"clean"`
		FindingCount int  `json:"findingCount"`
	} `json:"invariant"`
	Projection struct {
		Clean        bool `json:"clean"`
		FindingCount int  `json:"findingCount"`
		Findings     []struct {
			WalletID  string `json:"walletId"`
			Kind      string `json:"kind"`
			Projected string `json:"projected"`
			Actual    string `json:"actual"`
		} `json:"findings"`
	} `json:"projection"`
	MoneySupply struct {
		Clean       bool   `json:"clean"`
		LedgerClean bool   `json:"ledgerClean"`
		CachedClean bool   `json:"cachedClean"`
		LedgerTotal string `json:"ledgerTotal"`
		CachedTotal string `json:"cachedTotal"`
	} `json:"moneySupply"`
}

// runReconciliation triggers one pass on the Ledger Service. It returns the status code (200
// for any completed pass, drift included; 409 while another pass is running) and the report.
func runReconciliation(t *testing.T) (int, reconciliationReport) {
	t.Helper()
	resp, body := postWithKey(t, ledgerBaseURL+"/admin/reconciliation/run", "", "", "")
	var report reconciliationReport
	if resp.StatusCode == http.StatusOK {
		if err := json.Unmarshal([]byte(body), &report); err != nil {
			t.Fatalf("decode reconciliation report: %v; body: %s", err, body)
		}
	}
	return resp.StatusCode, report
}

func transferBody(source, destination uuid.UUID, amount string) string {
	return fmt.Sprintf(`{"sourceWalletId":"%s","destinationWalletId":"%s","amount":"%s"}`, source, destination, amount)
}

// postTransfer issues POST /transfers with the given Idempotency-Key and
// returns the response plus its already-read body (resp.Body is consumed).
func postTransfer(t *testing.T, token, idempotencyKey string, source, destination uuid.UUID, amount string) (*http.Response, string) {
	t.Helper()
	req, err := http.NewRequest(http.MethodPost, walletBaseURL+"/transfers", strings.NewReader(transferBody(source, destination, amount)))
	if err != nil {
		t.Fatalf("build transfer request: %v", err)
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer "+token)
	req.Header.Set("Idempotency-Key", idempotencyKey)
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("POST /transfers: %v", err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("read transfer response body: %v", err)
	}
	return resp, string(body)
}

type balanceResponse struct {
	WalletID string  `json:"walletId"`
	Balance  float64 `json:"balance"`
	Currency string  `json:"currency"`
	AsOf     string  `json:"asOf"`
	Stale    bool    `json:"stale"`
}

// pollBalance polls GET /wallets/{id}/balance every 200ms for up to 5s (the
// NFR-CONS-2 SLO) until want is reached, returning whatever it last observed
// either way so callers can assert on a timeout too. All E2E test amounts
// are whole-number BRL values, exactly representable as float64, so a direct
// equality check against want is safe here (no epsilon needed).
func pollBalance(t *testing.T, token string, walletID uuid.UUID, want float64) balanceResponse {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	var last balanceResponse
	for time.Now().Before(deadline) {
		resp := doRequest(t, http.MethodGet, fmt.Sprintf("%s/wallets/%s/balance", walletBaseURL, walletID), token, "")
		if resp.StatusCode == http.StatusOK {
			if err := json.NewDecoder(resp.Body).Decode(&last); err != nil {
				t.Fatalf("decode balance response: %v", err)
			}
			resp.Body.Close()
			if last.Balance == want {
				return last
			}
		} else {
			resp.Body.Close()
		}
		time.Sleep(200 * time.Millisecond)
	}
	return last
}

// assertLedgerEntryCount asserts accountID has exactly want rows in
// ledger_db.ledger_entries, connecting directly to Postgres as ledger_app
// (the same restricted role the Ledger Service itself runs as).
func assertLedgerEntryCount(t *testing.T, accountID uuid.UUID, want int) {
	t.Helper()
	conn, err := pgx.Connect(context.Background(), postgresDSN)
	if err != nil {
		t.Fatalf("connect to postgres: %v", err)
	}
	defer conn.Close(context.Background())

	var count int
	err = conn.QueryRow(context.Background(),
		"SELECT count(*) FROM ledger_db.ledger_entries WHERE account_id = $1", accountID).Scan(&count)
	if err != nil {
		t.Fatalf("query ledger_entries for account %s: %v", accountID, err)
	}
	if count != want {
		t.Errorf("ledger_entries count for account %s = %d, want %d", accountID, count, want)
	}
}

// assertLedgerEntriesForTransaction asserts transactionID has exactly want
// rows in ledger_db.ledger_entries.
func assertLedgerEntriesForTransaction(t *testing.T, transactionID uuid.UUID, want int) {
	t.Helper()
	conn, err := pgx.Connect(context.Background(), postgresDSN)
	if err != nil {
		t.Fatalf("connect to postgres: %v", err)
	}
	defer conn.Close(context.Background())

	var count int
	err = conn.QueryRow(context.Background(),
		"SELECT count(*) FROM ledger_db.ledger_entries WHERE transaction_id = $1", transactionID).Scan(&count)
	if err != nil {
		t.Fatalf("query ledger_entries for transaction %s: %v", transactionID, err)
	}
	if count != want {
		t.Errorf("ledger_entries count for transaction %s = %d, want %d", transactionID, count, want)
	}
}

// assertLedgerPostedObserved consumes ledger.posted.v1 from the start with a
// fresh consumer group (so it always sees the whole topic history) until it
// finds an event for transactionID or a 10s deadline elapses. Returns the
// matching record so callers can inspect its headers (e.g. NFR-OBS-2's
// traceparent propagation check).
func assertLedgerPostedObserved(t *testing.T, transactionID uuid.UUID) *kgo.Record {
	t.Helper()
	cl, err := kgo.NewClient(
		kgo.SeedBrokers(kafkaBroker),
		kgo.ConsumeTopics(ledgerTopic),
		kgo.ConsumeResetOffset(kgo.NewOffset().AtStart()),
		kgo.ConsumerGroup("e2e-"+uuid.New().String()),
	)
	if err != nil {
		t.Fatalf("kafka client: %v", err)
	}
	defer cl.Close()

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	for {
		fetches := cl.PollFetches(ctx)
		if ctx.Err() != nil {
			t.Fatalf("timed out waiting for LEDGER_POSTED for transaction %s on %s", transactionID, ledgerTopic)
		}
		var match *kgo.Record
		fetches.EachRecord(func(r *kgo.Record) {
			var event struct {
				TransactionID string `json:"transactionId"`
			}
			if err := json.Unmarshal(r.Value, &event); err == nil && event.TransactionID == transactionID.String() {
				match = r
			}
		})
		if match != nil {
			return match
		}
	}
}
